def tags(n):
    t=[]
    if "קיר" in n: t.append("מנורת קיר")
    if "תלוי" in n or "תלויה" in n: t.append("תלויה")
    if "צמוד" in n: t.append("צמודת תקרה")
    if not t: t.append("גוף תאורה")
    return t

